var _ = types.AddType(&types.Type{Name: "github.com/WaveReality/waves/wavesim.Units", IDName: "units", Doc: "Units establishes a consistent set of units for computing\nphysics-based [Parameter] factors. Length units are in terms\nof individual cubic elements.", Fields: []types.Field{{Name: "ComptonE", Doc: "ComptonE is the compton hbar wavelength of an electron in cubic elements,\ni.e., how many cubes long is the Compton wavelength of the electron.\nThis fixes the length dimension of a cube, as the inverse of this times\nthe numerical value of this quantity (LambdaBarE). It also fixes the EMass."}, {Name: "C", Doc: "C is the speed of light in a vacuum in units of cube length / time step.\nFor Dirac waves, 0.5 is the maximum stable value. This fixes the time\nscale given the length scale from ComptonE."}, {Name: "Hbar", Doc: "Hbar = h / 2pi = reduced Planck constant, which determines the mass scale\ngiven length (from ComptonE) and time (from C)."}, {Name: "E", Doc: "E is the electric charge constant in cubic units, which determines the\nelectric potential units, C = A s\n0.302822 causes Mu0 and Eps0 to both be 1, if C and Hbar are both 1"}, {Name: "EMass", Doc: "EMass is the rest mass of the electron, in cubic units."}, {Name: "Mu0", Doc: "Mu0 is the computed Mu0 magnetic constant, permeability of free space\nN/A^2 = m kg / s^2 A^2"}, {Name: "Eps0", Doc: "Eps0 is the computed Eps0 electric constant, permittivity of free space\nF/m = (s^4 A^2) / (m^3 kg)"}, {Name: "HiggsCompton", Doc: "HiggsCompton is the reduced Compton wavelength of the Higgs boson,\nin cubic elements: how many cubes long is hbar / (m_h c). This is the\nsingle free scale knob for the electroweak sector, playing the same role\nthere that ComptonE plays for the electron. It is independent of ComptonE\nbecause the two scales are 2.4e5 apart and cannot share a lattice.\nValues of 16 or more keep m_h, m_W and m_Z all well resolved."}, {Name: "HiggsMh", Doc: "HiggsMh is the Higgs mass in inverse cube units (1/cube),\n= 1 / HiggsCompton."}, {Name: "HiggsLambda", Doc: "HiggsLambda is the quartic coupling of the Higgs potential. It is\ndimensionless, so this is just the Standard Model value, unconverted."}, {Name: "HiggsMu", Doc: "HiggsMu is the mu parameter of the Higgs potential, m_h / sqrt(2),\nin INVERSE cube units (1/cube) -- an inverse Compton wavelength, not a\nmass. Its square fills the same slot in the update as (m c / hbar)^2\ndoes in Klein-Gordon."}, {Name: "HiggsV", Doc: "HiggsV is the Higgs vacuum expectation value, mu / sqrt(lambda), in\ninverse cube units (1/cube). This is the radius of the minimum of the\npotential, i.e. the value the neutral component settles at."}, {Name: "GW", Doc: "GW is g, the SU(2)_L gauge coupling: dimensionless, hence the\nStandard Model value unconverted."}, {Name: "GpW", Doc: "GpW is g', the U(1)_Y gauge coupling: likewise dimensionless."}, {Name: "MW", Doc: "MW is the resulting W boson mass, g v / 2, in 1/cube."}, {Name: "MZ", Doc: "MZ is the resulting Z boson mass, v sqrt(g^2+g'^2) / 2, in 1/cube."}, {Name: "ThetaW", Doc: "ThetaW is the weak mixing angle, atan(g'/g), in degrees."}, {Name: "CuM", Doc: "CuM is the computed length of a cubic element, in meters."}, {Name: "CuS", Doc: "CuS is the computed duration of a time step update, in seconds."}, {Name: "CuKg", Doc: "CuKg is the computed cube unit of mass, in Kg."}, {Name: "CuN", Doc: "CuN is the computed unit of force, in Newtons: kg m / s^2."}, {Name: "CuJ", Doc: "CuJ is the computed unit of energy, in Joules: N m = kg m^2 / s^2."}, {Name: "CuW", Doc: "CuW is the computed unit of power, in Watts: J / s = kg m^2 / s^3."}, {Name: "CuA", Doc: "CuA is the computed unit of current, in Ampheres: A = C / s; Esi / (E * S)."}, {Name: "CuC", Doc: "CuC is the computed cube unit of charge, in Coulombs: C = A * s."}, {Name: "CuV", Doc: "CuV is the computed unit of electrical potential, in Volts: V = W / A = kg m^2."}, {Name: "CuF", Doc: "CuF is the computed unit of capacitance, in Farads = C / V: 1/kg 1/m^2 s^4 A^2"}, {Name: "Csi", Doc: "Csi is the speed of light, m/s"}, {Name: "HbarSi", Doc: "Hbar is the normalized Planck constant h / (2 Pi) = J s = m^2 kg / s"}, {Name: "Esi", Doc: "Esi is the unit of electrical charge: C = A s"}, {Name: "EMassSi", Doc: "EMassSi is the electron rest mass kg"}, {Name: "Mu0si", Doc: "Mu0 is the magnetic constant, permeability of free space\nN/A^2 = (m kg) / (s^2 A^2)"}, {Name: "Eps0si", Doc: "Eps0 is the electric constant, permittivity of free space = 1 / (mu0 c^2)\nF/m = (s^4 A^2) / (m^3 kg)"}, {Name: "Alpha", Doc: "Alpha is the fine structure constant: e^2 / (hbar c 4pi eps0) (dimensionless)"}, {Name: "LambdaEsi", Doc: "LambdaEsi is the Compton wavelength of the electron rest mass:\nh / (m0 c) = (2 pi hbar) / (m0 c) = 2.42631e-12 m"}, {Name: "LambdaBarEsi", Doc: "LambdaBarEsi is the Compton wavelength of the electron rest mass in hbar\nhbar / (m0 c) = 3.8615926771197e-13 m"}, {Name: "A0si", Doc: "A0 is the Bohr radius in hbar: hbar / (m0 c alpha) = 5.2917720859e-11 m"}}})

var _ = types.AddType(&types.Type{Name: "github.com/WaveReality/waves/wavesim.PanelView", IDName: "panel-view", Doc: "PanelView for what each panel in the View renders.", Fields: []types.Field{{Name: "Var", Doc: "Variable to display."}, {Name: "CurPrev", Doc: "Select which state to view"}, {Name: "Mode", Doc: "Mode is how the state values are displayed for this panel."}, {Name: "Offset", Doc: "Offset is an additional offset from the global Start,\nenforced to be within the displayable size."}}})

var _ = types.AddType(&types.Type{Name: "github.com/WaveReality/waves/wavesim.View", IDName: "view", Doc: "View is a Cogent Core Widget that provides a 3D view into state.", Embeds: []types.Field{{Name: "Frame"}, {Name: "Mutex"}}, Fields: []types.Field{{Name: "Var", Doc: "Var determines the set of variables being used.\nactual variable to view is in the PanelView."}, {Name: "Panels", Doc: "Pannels are the view settings per panel (4 max)."}, {Name: "Start", Doc: "Starting front-left corner location within state."}, {Name: "Size", Doc: "Size of planes"}, {Name: "Depth", Doc: "Depth is the state dimension drawn going back into the screen, which\npicks the plane: display X is always state X and height is the value.\n[math32.Z] is the standard orientation and default (X-Z sliced at a Y\nlevel); [math32.Y] gives X-Y sliced at Z, for a flat sim with a single\nZ. The leftover dimension is [View.SliceDim], positioned by Start."}, {Name: "VarSettings", Doc: "parameters for the list of variables to view"}, {Name: "Settings", Doc: "Settings are parameters controlling how the view is rendered"}, {Name: "Counters", Doc: "Counters are displayed at the bottom: time, etc."}, {Name: "colorMap", Doc: "color map for mapping values to colors -- set by name in Settings"}, {Name: "curPanel", Doc: "which panel are we currently updating"}, {Name: "curNPanels", Doc: "current number of panels rendered -- if changes, do full rebuild."}, {Name: "selCube"}, {Name: "sim"}, {Name: "midFrame"}, {Name: "scene"}, {Name: "counters", Doc: "SceneDBG  *Scene"}, {Name: "varsFrame"}, {Name: "toolbar"}, {Name: "viewbar"}}})

// NewView returns a new [View] with the given optional parent:
// View is a Cogent Core Widget that provides a 3D view into state.
func NewView(parent ...tree.Node) *View { return tree.New[View](parent...) }

// SetPanels sets the [View.Panels]:
// Pannels are the view settings per panel (4 max).
func (t *View) SetPanels(v [4]PanelView) *View { t.Panels = v; return t }

// SetStart sets the [View.Start]:
// Starting front-left corner location within state.
func (t *View) SetStart(v math32.Vector3i) *View { t.Start = v; return t }

// SetSize sets the [View.Size]:
// Size of planes
func (t *View) SetSize(v math32.Vector3i) *View { t.Size = v; return t }

// SetVarSettings sets the [View.VarSettings]:
// parameters for the list of variables to view
func (t *View) SetVarSettings(v map[enums.Enum]*VarSettings) *View { t.VarSettings = v; return t }

// SetSettings sets the [View.Settings]:
// Settings are parameters controlling how the view is rendered
func (t *View) SetSettings(v Settings) *View { t.Settings = v; return t }

var _ = types.AddType(&types.Type{Name: "github.com/WaveReality/waves/wavesim.WaveStates", IDName: "wave-states", Doc: "WaveStates are the state variables for Wave equations."})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.DiracKernel", Doc: "DiracKernel is the second-order (Feynman-Gell-Mann) Dirac equation: the\ncomplex Klein-Gordon equation on TWO complex components, plus one term.\n\n\t[(i hbar d_mu - (e/c) A_mu)^2 + (e/c) sigma . (B + iE)] psi = m^2 c^2 psi\n\nEverything but the last term acts on the two components separately, exactly\nas KleinGordonCKernel acts on one. The sigma term is what makes this Dirac\nrather than two copies of KG: it mixes components 1 and 2, and that mixing\nis spin.\n\nTwo things about it are worth knowing. The free equation has NO spin term at\nall -- a free particle here is four uncoupled KG waves, and spin only shows\nup through the field. That is not a defect: spin is not observable on a free\nparticle either, it takes a field gradient to see one. And the strength of\nthe term is fixed, not free: it is what makes the magnetic moment come out\nat g = 2, which is the second-order equation's best-known prediction.\n\nIn c = 1 units the combination is B + iE. Here it is cB + iE, because E and\nB differ by a factor of c in these units -- E = -grad A0 - dA/dt is per step\nwhere B = curl A is per cube. [Sim.MaxwellStats] measures exactly that ratio.", Directives: []types.Directive{{Tool: "gosl", Directive: "kernel"}}, Args: []string{"i"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.SpinAtRest", Doc: "SpinAtRest is a gaussian lump of charge at rest with its spin along +Z: the\nelectron, as far as this equation has one.\n\nNothing visibly happens to the spin, and that is the equation being honest.\nThe free second-order equation has no spin term at all -- it is four\nuncoupled Klein-Gordon waves -- so a free particle does not precess, wobble\nor do anything else you could point at. Spin is not observable on a free\nparticle in the real world either; it takes a field. Run SpinPrecession for\nthat, and watch the charge here instead, which is conserved exactly.", Args: []string{"ss"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.SpinPrecession", Doc: "SpinPrecession puts the spin along +X in a uniform magnetic field along Z,\nwhere it turns about the field at the Larmor frequency\n\n\tomega = g e B / (2 m c),  with g = 2\n\nThat g = 2 is the whole reason for the sigma . F term, and it is not tuned:\nit comes out of the coefficient the equation already has. Watch SigX and\nSigY in the stats trade off against each other while SigZ stays flat.\n\nBZ is set directly rather than built from a vector potential, which isolates\nthe spin term from the orbital ones. It is not a self-consistent Maxwell\nfield, so leave Params.EM on but do not expect the field to evolve.", Args: []string{"ss"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.SpinInPotential", Doc: "SpinInPotential puts an electron in a Coulomb well: a Dirac lump at rest,\noffset from a fixed 1/r scalar potential, which pulls it in.\n\nThe potential is EXTERNAL: Params.SelfField is off, so MaxwellKernel does\nnot run and A0 stays exactly as set here. That matters, because the Dirac\nkernel overwrites Charge every step with the wave's own charge, so a nucleus\nleft in that variable would be erased on the first step. Putting the\npotential straight into A0 is both simpler and closer to what an electron\nin a given external field actually means.\n\nThe well depth is scaled to a fraction of the rest energy, for the reason in\nkgSelfScale: once e A0 approaches m c^2 the single-particle equation is in\nthe Klein regime and stops describing one particle.\n\nEdges are damped, so the parts of the lump that are not held by the well can\nleave rather than wrapping round and coming back.", Args: []string{"ss"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.diracAtom", Doc: "DiracConfigs are the initialization options offered in the GUI.\ndiracAtom is the shared setup for the two bound-state configs, as\nscalarAtom is for the complex Klein-Gordon ones.", Args: []string{"ss", "a", "n"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.DiracHydrogen", Doc: "DiracHydrogen is a spin-1/2 electron bound in a Coulomb well: the closest\nthis gets to a real hydrogen atom, since the electron is now a fermion with\nspin rather than the scalar of ScalarHydrogen.\n\nThe shape is the nonrelativistic exp(-r/a) in the spin-up component alone,\nwhich is an eigenstate to order (Z alpha)^2. What the Dirac equation adds\nover the scalar case is the sigma . (cB + iE) term: the nucleus has a radial\nE field, so the spin now feels the orbit it is in. That is spin-orbit\ncoupling, and it is the origin of fine structure -- the reason the levels of\na real atom split by spin rather than depending only on n.\n\nWatch SigZ: it holds, because an s state has no orbital angular momentum for\nthe spin to couple to. DiracHydrogenP is where that changes.", Args: []string{"ss"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.DiracHydrogenP", Doc: "DiracHydrogenP is the 2p orbital with spin: two lobes of opposite phase,\nspin up, in a well four times deeper so it comes out the size of the ground\nstate above.\n\nThis one has both spin and orbital angular momentum, so the sigma . (cB + iE)\nterm genuinely acts and the state is not quite stationary: what is conserved\nis the total j, not the two separately. The p orbital of a real atom splits\ninto j = 1/2 and j = 3/2 for exactly this reason, and a spin-up l = 1 state\nis a mixture of the two, so it evolves rather than sitting still.", Args: []string{"ss"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EdgesWrapKernel", Doc: "EdgesWrapKernel is the kernel for wrapping edge values", Directives: []types.Directive{{Tool: "gosl", Directive: "kernel"}}, Args: []string{"i"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EWGaugeAct", Doc: "EWGaugeAct returns -i * G * Psi in real components, where G is the Hermitian\n2x2 gauge matrix that the covariant derivative is built from:\n\n\tG = g W^a T^a + g' Y_Phi B,   T^a = sigma^a / 2\n\t  = [[ du, or + i oi ], [ or - i oi, dd ]]\n\tdu = (g/2) W3 + g' Y B      or = (g/2) W1\n\tdd = -(g/2) W3 + g' Y B     oi = -(g/2) W2\n\nThe opposite sign of W3 on the diagonal is T^3 = +-1/2: why the upper and\nlower components feel W3 oppositely but B identically. The combination\nannihilating the vacuum is Q = T^3 + Y, the one massless direction.\n\nThis one operation is the entire gauge coupling: D_mu Psi = d_mu Psi +\nEWGaugeAct(W_mu, B_mu, Psi), and the covariant Laplacian composes from it.\nPsi is the doublet as four reals, (X + iY, Z + iW) = sqrt(2) Phi.", Args: []string{"w1", "w2", "w3", "b", "psi"}, Returns: []string{"Vector4"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EWCurrent", Doc: "EWCurrent returns the four gauge currents that a doublet Psi with covariant\nderivative d = D_mu Psi puts into the gauge fields at spacetime index mu:\n\n\tX,Y,Z = j^a_mu = 2 g  Im[Phi^dag T^a D_mu Phi]   (a = 1,2,3, sourcing W^a)\n\tW     = j^Y_mu = 2 g' Y Im[Phi^dag D_mu Phi]     (sourcing B)\n\nwith Phi = Psi/sqrt(2) folding one factor of 1/2 into each expression.\n\nNOTHING in this kernel contains a gauge boson mass term. The masses arise\nbecause Psi is non-zero everywhere: evaluated at the vacuum this current\nreduces to exactly -m^2 times the gauge field itself, uniformly and\npermanently. That feedback is the Higgs mechanism.", Args: []string{"psi", "d"}, Returns: []string{"Vector4"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EWDiv", Doc: "EWDiv returns the lattice divergence of a 3-vector gauge potential whose\nX, Y, Z components are the three consecutive state variables at vX.", Args: []string{"x", "y", "z", "vX", "tidx"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EWCrossUp", Doc: "EWCrossUp returns sum_mu (A^mu x B_mu), the contraction of an UPPER with a\nLOWER spacetime index. No metric signs: all four terms add.\n\nEvery eps^{abc} in the Yang-Mills equation is a cross product in adjoint\nspace, since eps^{abc} X^b Y^c = (X x Y)^a. Writing the self-coupling this\nway turns a triple-index mess into four cross products.", Args: []string{"a0", "ax", "ay", "az", "b0", "bx", "by", "bz"}, Returns: []string{"Vector3"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EWCrossLor", Doc: "EWCrossLor returns sum_mu (A_mu x B^mu) where BOTH carry the same index\nposition, so the (+,-,-,-) metric appears: time adds, space subtracts.", Args: []string{"a0", "ax", "ay", "az", "b0", "bx", "by", "bz"}, Returns: []string{"Vector3"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EWBorisRot3", Doc: "EWBorisRot3 is the Boris rotation for an adjoint 3-vector velocity: the\nEXACT, norm-preserving update for dv/dt = v x Omega over one unit step.\n\n\tt = Omega/2 ;  v' = v + v x t ;  v+ = v + v' x (2t / (1 + |t|^2))\n\nThe two half-turns compose into a true rotation, which is the whole point:\nthe velocity-dependent gauge force does not change |v|, and an explicit\nupdate gets that wrong at O(Omega^2) EVERY step, which is what makes the\nrotating-frame system blow up.", Args: []string{"v", "om"}, Returns: []string{"Vector3"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EWBorisPhase", Doc: "EWBorisPhase rotates the Higgs velocity by exp(i theta G_0), the exact\nsolution of the velocity-dependent part of the Higgs equation,\n\n\tdv/dt = -2c (-i G_0) v = 2ic G_0 v   ->   v(1) = exp(2ic G_0) v(0)\n\nso theta = 2c. For the 2x2 Hermitian gauge matrix this has a closed form:\nsplitting G_0 = alpha I + m.sigma, with\n\n\tm = (g/2) (W^1_0, W^2_0, W^3_0)   and   alpha = g' Y_Phi B_0\n\nthe exponential is\n\n\texp(i theta alpha) * (cos(theta |m|) I + i sin(theta |m|) mhat.sigma)\n\nThe SU(2) part turns the doublet, the U(1) part is an overall phase: the\nparallel transport the connection generates.", Args: []string{"w1", "w2", "w3", "b", "theta", "v"}, Returns: []string{"Vector4"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.ElectroweakKernel", Doc: "ElectroweakKernel is the kernel for the SU(2)_L x U(1)_Y electroweak model:\nthe Higgs doublet coupled to the three W^a gauge fields and the B field.\nOnly supports 3D.\n\n# Fields\n\nThe Higgs doublet is four real fields,\n\n\tPhi = (1/sqrt2) ( hsCa + i hsCb , hs0a + i hs0b )^T\n\nso mag = hsCa^2 + hsCb^2 + hs0a^2 + hs0b^2 = 2 Phi^dag Phi. The vacuum\n<Phi> = (0, v/sqrt2)^T is hs0a = v, rest zero. It MUST be the neutral\n(lower) component, or Q = T^3 + Y does not annihilate the vacuum and the\nphoton gains mass.\n\nEach gauge field is a four-potential (0, X, Y, Z) with its own velocity, as\nin MaxwellKernel, evolved in Lorenz gauge:\n\n\tbox W^a_mu = j^a_mu,    box B_mu = j^Y_mu\n\n# Units\n\nInverse cube units (1/cube) throughout, which is what makes g, g' and lambda\nthe bare dimensionless SM numbers (see Units.Update).\n\n# Yang-Mills self-coupling\n\nEnabled by Params.YangMills. With a Feynman-type gauge-fixing term (xi = 1)\ncancelling the -d^nu(d.W) piece, the non-abelian equation of motion is\n\n\tbox W^a_nu = j^a_nu\n\t             + g eps^abc (d.W^b) W^c_nu                  [divergence]\n\t             + 2g eps^abc W^{b mu} d_mu W^c_nu           [transport]\n\t             - g eps^abc W^b_mu d^nu W^{c mu}            [transpose]\n\t             - g^2 eps^abc eps^cde (W^b.W^d) W^e_nu      [quartic]\n\nThe three CUBIC signs are fixed by requiring force = -dU/dphi for the energy\nwith F^a_jk = d_j W^a_k - d_k W^a_j + g eps^abc W^b_j W^c_k; see\nTestElectroweakForceIsEnergyGradient. The pure-gauge test cannot fix them:\nflipping the signs also reverses the rotation sense it predicts, so it\npasses either way. The quartic sign is independent, checked on uniform\nfields.\n\nThe divergence term is kept, not dropped: unlike the abelian case d.W^a = 0\nis NOT preserved by the non-abelian evolution, so it cannot be imposed.\n\nAll four terms are quadratic or cubic in W, so they vanish at linear order\nand leave the spectrum unchanged. What they add is the W self-interaction:\nthe difference between SU(2) and three copies of U(1).", Directives: []types.Directive{{Tool: "gosl", Directive: "kernel"}}, Args: []string{"i"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EWWStep", Doc: "EWWStep advances the twelve SU(2) potentials. src carries the\nvelocity-INDEPENDENT source (current + the explicit Yang-Mills terms) for one\nspacetime index, as an adjoint 3-vector; the Laplacian is added here.\n\nWith Boris on, the velocity-dependent transport term -- which is exactly\ndv/dt = v x Omega with Omega = -2 g c W_0 -- is applied as a true rotation\nbetween two half kicks, instead of being lumped into the explicit force.", Args: []string{"x", "y", "z", "cur", "prv", "nu", "csq", "om", "src", "boris", "noWave"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EWGaugeStep", Doc: "EWGaugeStep advances one four-potential (the 0,X,Y,Z state variables\nstarting at v0, with their four velocities at v0+4) by one leapfrog step of\n\n\td2 A_mu / dt2 = c^2 [ lap(A_mu) + j_mu ]\n\nwhich is box A_mu = j_mu in Lorenz gauge -- the same equation MaxwellKernel\nsolves for the photon, with the electroweak current in place of the\nelectromagnetic one. No mass term appears here or anywhere else.", Args: []string{"x", "y", "z", "cur", "prv", "v0", "csq", "j0", "jx", "jy", "jz", "noWave"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.ElectroweakViewAll", Doc: "ElectroweakViewAll configures the View to display Electroweak values", Args: []string{"view"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.ewDemoScale", Doc: "ewDemoScale raises the electroweak scale so m_W and m_Z are comparable to a\npacket a few tens of cubes long. At the SM scale the boson Compton\nwavelengths are ~22 cubes, so a visible packet is far above threshold and the\nZ would run at 0.97 c. g and g' are untouched, so the mixing angle and\nm_W / m_Z stay physical.", Args: []string{"ss", "mu"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.ewVZero", Doc: "ewVZero returns the zero-temperature vacuum value, mu/sqrt(lambda): still\nthe natural amplitude scale when Temp has driven HiggsV to zero.", Args: []string{"ss"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.HiggsBroken", Doc: "HiggsBroken initializes the vacuum is <Phi> = (0, v/sqrt2)^T, i.e.\nthe NEUTRAL (lower) component holds the VEV, with magnitude\nv = mu/sqrt(lambda) -- not mu. Putting it\nin the charged component instead would leave Q = T^3 + Y broken\nand give the photon a mass.", Args: []string{"ss"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.HiggsSymmetric", Doc: "HiggsSymmetric starts every Higgs component at zero plus a whisper of noise,\nand lets the field fall off the top of the Mexican hat into the broken vacuum.\nAny deviation of \\Phi off of 0 is enough to knock it off of the unstable maximum.\n\nAdjusting Temp around TempCrit changes the shape of the potential: if above\nTempCrit then it is symmetric and the zero remains stable, not unstable.\n\nEWHmag climbs from 0 to v^2, but overshoots and rings rather than settling,\nbecause nothing here dissipates. In the early universe Hubble\nexpansion drained it, and there is no equivalent in a fixed box.\nNote: it takes a while, around 700 time steps at default params.", Args: []string{"ss"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.PhotonPulse", Doc: "PhotonPulse sends a transverse electromagnetic pulse along X at exactly the\nspeed of light.\n\nThe packet is written in the PHYSICAL basis: the photon is the combination\nsin(theta_W) W^3 + cos(theta_W) B, the direction that Q = T^3 + Y annihilates,\nso the condensate gives it no mass and it moves at c. Watch AYs.", Args: []string{"ss"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.ZPulse", Doc: "ZPulse sends a Z boson pulse along X, which travels SLOWER than light.\nBecause Z is cos(theta_W) W^3 - sin(theta_W) B, that direction does not\nannihilate the vacuum, so it takes mass m_Z from the condensate and the\npacket moves at the group velocity:\n\n\tv_g = c khat / sqrt(khat^2 + m_Z^2)\n\nwhich would be about 0.70 c here, vs 0.98 c for the photon. Watch ZY.\nWith the default [Config.Amplitude] of 1, it melts the condensate it\npasses through to about a third of vacuum, and a lighter Z travels faster.\n\nNote this raises the Higgs scale, for the reason given in ewDemoScale.", Args: []string{"ss"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.WCollision", Doc: "WCollision fires two W packets at each other. They do not bounce -- gauge\nfields pass through each other -- but the Yang-Mills eps^abc W^b W^c term\nmeans a W^1 and a W^2 generate W^3 where they overlap, out of nothing. Turn\noff Params.YangMills and they cross without a trace: that is the whole\ndifference between SU(2) and three copies of U(1).\n\nWatch W3Xs, and ZX built from it. X, not Y: both packets are polarised along\nY and travel along X, so W^{b mu} d_mu vanishes and the transport term is\nsilent. The surviving transpose term sources the LONGITUDINAL W^3_x, which\nfor a massive vector is physical -- the eaten Goldstone. A single packet\ngenerates exactly zero. With wrapped edges the pair re-collides every lap,\nso the signal accumulates rather than peaking.\n\nThe envelope width is set here rather than from Config.PacketWidth: the\npackets start 40% of the box apart, and the 1.5 wl default has them already\noverlapping at half amplitude. On a 100-wide box 1.5 wl gives 50% overlap at\nt=0, 1.2 wl 34%, 0.75 wl 6% -- the first that looks like a collision. The\nlarge amplitude pays for that: the source is quadratic in W, so 0.1 v ->\n0.25 v wins back 6x of the 260x the narrower envelope costs.", Args: []string{"ss"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.ElectroweakStaticEnergy", Doc: "ElectroweakStaticEnergy is the potential (no time derivative) part of the\nelectroweak energy, evaluated over the interior of the lattice:\n\n\tU = sum_x [ (1/2) sum_j |D_j Psi|^2                     Higgs gradient\n\t          + V(mag)                                      Higgs potential\n\t          + (1/4) sum_{a,j,k} (F^a_jk)^2                W magnetic\n\t          + (1/4) sum_{j,k} (Fb_jk)^2                   B magnetic\n\t          + (1/2) sum_a (div W^a)^2 + (1/2)(div B)^2 ]  gauge fixing\n\nwith the full non-abelian field strength\n\n\tF^a_jk = d_j W^a_k - d_k W^a_j + g eps^abc W^b_j W^c_k\n\nThe gauge-fixing term is the xi = 1 (Feynman) choice the kernel assumes;\nwith the magnetic term it makes the abelian part of -dU/dW the plain\nLaplacian.\n\nA host-side diagnostic for checking the kernel's force is -dU/dphi. NOT\nexact at finite spacing: Laplacian19 and Gradient10 are not adjoint\ncompatible (Fourier symbols differ by O(k^2)), so the agreement is a\ncontinuum-limit statement, which TestElectroweakForceIsEnergyGradient\nmeasures.\n\nOnly W_0 = B_0 = 0 is covered: with a time component the conserved\nfunctional is the indefinite Feynman-gauge one, whose cubic term mixes\nkinetic and potential pieces.", Returns: []string{"float64"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.ElectroweakStaticEnergyNear", Doc: "ElectroweakStaticEnergyNear sums the energy over the 27 sites centred on\n(x,y,z). Every stencil reaches at most one cube, so the derivative of the\nTOTAL energy w.r.t. one site lives entirely in this block. That makes the\nnumerical-gradient check boundary-independent, so the test field need not be\nlattice-periodic.", Args: []string{"x", "y", "z"}, Returns: []string{"float64"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.ewWVec", Doc: "ewWVec returns the adjoint triplet (W^1_c, W^2_c, W^3_c) for spatial\ncomponent c (0=X, 1=Y, 2=Z) at one site.", Args: []string{"x", "y", "z", "c", "tidx"}, Returns: []string{"Vector3"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.ewSiteEnergy", Args: []string{"x", "y", "z", "g", "p"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.slCross", Args: []string{"a", "b"}, Returns: []string{"Vector3"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.FormDialog", Doc: "FormDialog opens a dialog in a new, separate window\nfor viewing / editing the given struct object, in\nthe context of the given ctx widget.", Args: []string{"ctx", "v", "title"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.Laplacian1D", Doc: "Laplacian1D computes the 1D Laplacian across 2 X dim neighbors,\nfor given x,y,z center coordinates, variable index vidx,\nand cur / prev time index tidx. ctr is the center value.", Args: []string{"x", "y", "z", "vidx", "tidx", "ctr"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.Laplacian19", Doc: "Laplacian19 computes the 3D Laplacian over the 18 face and edge neighbors\nplus the center (the 19-point stencil),\nfor given x,y,z center coordinates, variable index vidx,\nand cur / prev time index tidx. ctr is the center value.", Args: []string{"x", "y", "z", "vidx", "tidx", "ctr"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.NeighAverage27", Doc: "NeighAverage27 computes the 3D average across 27 neighbors,\nincluding the center, for given x,y,z center coordinates, variable index vidx,\nand cur / prev time index tidx. ctr is the center value.", Args: []string{"x", "y", "z", "vidx", "tidx"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.NeighMax26", Doc: "NeighMax26 returns which neighbor cell index (into NeighOffs offsets)\nhas the largest value among the 26 3D neighbors.\nfor given x,y,z center coordinates, variable index vidx,\nand cur / prev time index tidx.", Args: []string{"x", "y", "z", "vidx", "tidx"}, Returns: []string{"int32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.NeighValue", Doc: "NeighValue returns value at given neighbor cell index\n(into NeighOffs offsets), for given x,y,z center coordinates,\nvariable index vidx, and cur / prev time index tidx.", Args: []string{"nidx", "x", "y", "z", "vidx", "tidx"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.Gradient1D", Doc: "Gradient10 computes the 3D gradient from 5 antipodal pairs (10 points),\nfor given x,y,z center coordinates, variable index vidx,\nand cur / prev time index tidx.\nGradient1D computes the gradient along X only, as a centered difference:\nthe 1D counterpart of [Gradient10], for non-ThreeD runs.", Args: []string{"x", "y", "z", "vidx", "tidx"}, Returns: []string{"Vector3"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.Gradient10", Args: []string{"x", "y", "z", "vidx", "tidx"}, Returns: []string{"Vector3"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.Divergence10", Doc: "Divergence10 computes the 3D divergence from 5 antipodal pairs (10 points)\nper direction,\nfor given x,y,z center coordinates, variable index vidx,\nand cur / prev time index tidx. Div = sum of gradients.", Args: []string{"x", "y", "z", "vidx", "tidx", "dx", "dy", "dz"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.Curl10", Doc: "Curl10 computes the 3D curl from 5 antipodal pairs (10 points) per\ndirection, on a field vector,\nfor given x,y,z center coordinates, variable index vidx (to X component),\nand cur / prev time index tidx.", Args: []string{"x", "y", "z", "vidx", "tidx"}, Returns: []string{"Vector3"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EdgeInBounds1", Doc: "EdgeInBounds1 returns true if given coordinate is >= 1 and < s.", Args: []string{"x", "y", "z", "sx", "sy", "sz"}, Returns: []string{"bool"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.EdgeInBounds0", Doc: "EdgeInBounds0 returns true if given coordinate is >= 0 and <= s.", Args: []string{"x", "y", "z", "sx", "sy", "sz"}, Returns: []string{"bool"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.LaplacianEdge1D", Doc: "LaplacianEdge1D computes the 1D Laplacian across 2 X dim neighbors,\nfor given x,y,z center coordinates, variable index vidx,\nand cur / prev time index tidx. ctr is the center value.\nFor computation at the edge, checks against given full size bounds.", Args: []string{"x", "y", "z", "sx", "sy", "sz", "vidx", "tidx", "ctr"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.LaplacianEdge19", Doc: "LaplacianEdge19 computes the 19-point 3D Laplacian,\nfor given x,y,z center coordinates, variable index vidx,\nand cur / prev time index tidx. ctr is the center value.\nFor computation at the edge, checks against given full size bounds.", Args: []string{"x", "y", "z", "sx", "sy", "sz", "vidx", "tidx", "ctr"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.PotentialEnergy1D", Doc: "PotentialEnergy1D computes the 1D potential energy across 2 neighbors,\nfor given x,y,z center coordinates, variable index vidx,\nand cur / prev time index tidx. ctr is the center value.", Args: []string{"x", "y", "z", "vidx", "tidx", "ctr"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.PotentialEnergy19", Doc: "PotentialEnergy19 computes the 3D potential energy over the 19-point stencil,\nfor given x,y,z center coordinates, variable index vidx,\nand cur / prev time index tidx. ctr is the center value.", Args: []string{"x", "y", "z", "vidx", "tidx", "ctr"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.GetRandomNumber", Doc: "GetRandomNumber returns a random number that depends on the index,\ncounter and function index.\nWe increment the counter after each cycle, so that we get new random numbers.\nThis whole scheme exists to ensure equal results under different multithreading settings.", Args: []string{"index", "counter", "funIndex"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.GPUInit", Doc: "GPUInit initializes the GPU compute system,\nconfiguring system(s), variables and kernels.\nIt is safe to call multiple times: detects if already run."})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.GPURelease", Doc: "GPURelease releases the GPU compute system resources.\nCall this at program exit."})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.RunDiracKernel", Doc: "RunDiracKernel runs the DiracKernel kernel with given number of elements,\non either the CPU or GPU depending on the UseGPU variable.\nCan call multiple Run* kernels in a row, which are then all launched\nin the same command submission on the GPU, which is by far the most efficient.\nMUST call RunDone (with optional vars to sync) after all Run calls.\nAlternatively, a single-shot RunOneDiracKernel call does Run and Done for a\nsingle run-and-sync case.", Args: []string{"n"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.RunDiracKernelGPU", Doc: "RunDiracKernelGPU runs the DiracKernel kernel on the GPU. See [RunDiracKernel] for more info.", Args: []string{"n"}})

