var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.StateAt", Doc: "StateAt returns the value of the given variable at the cell nearest to pos,\nin non-edge coordinates, clamped to the interior.", Args: []string{"sz", "vri", "pos", "curPrv"}, Returns: []string{"float32"}})

var _ = types.AddFunc(&types.Func{Name: "github.com/WaveReality/waves/wavesim.StateAtInterp", Doc: "StateAtInterp returns the trilinearly interpolated value of the given\nvariable at pos, in non-edge coordinates, clamped to the interior.\n\nInterpolated rather than nearest-cell because the radial stats compare an\naxis against a diagonal: [CoordToInt] truncates, which along a diagonal\nshortens the radius by up to 13% and reads as an anisotropy that is not\nthere.", Args: []string{"sz", "vri", "pos", "curPrv"}, Returns: []string{"float32"}})

